//! Recompiled routines: Rust versions of the program's seg000 routines
//! (generated by `crates/lift` into `crates/dune-rec`), called in place of the
//! original when the CPU reaches their entry.
//!
//! A routine runs on the same machine state as the interpreter: registers in
//! [`crate::Cpu`], memory in [`crate::Hardware`], return addresses on the
//! emulated stack. It returns `Ok` after its `RET`, with CS:IP set to where
//! that `RET` went. When it meets something it does not handle natively it
//! returns [`Bail`]; the state is then at an instruction boundary and the
//! interpreter simply carries on from CS:IP. Bailing is always safe.
//!
//! Modes ([`RecMode`]):
//! - `On`: routines replace the original. Interrupts are not delivered while
//!   one runs; code that needs devices to progress (an `INT`, a far call into
//!   a driver) makes the routine bail so the run loop handles it.
//!   After a bail the interpreter runs until it reaches any block leader of a
//!   routine, where Rust takes over again.
//! - `Shadow`: the original runs as usual (interrupts, devices, nested
//!   routines). For the first [`Rec::samples`] calls of each routine the entry
//!   state is kept, and everything the program receives from outside the CPU
//!   is recorded ([`crate::hw::IoLog`]: port reads, hardware interrupts with
//!   the instruction they came before, BIOS/DOS results). When the original
//!   returns, the Rust version is replayed from the entry state, fed from
//!   that log, and registers, flags and all memory are compared; a replay
//!   that does different I/O is a difference too. The original's result is
//!   what the game continues with. In a replay, a call whose callee bails
//!   (an interrupt due inside it, a wait for one) finishes the callee
//!   there, interpreting with the recorded interrupts and resuming Rust at
//!   block leaders, and then goes on in the caller's Rust code: a routine
//!   that calls a waiting one is still checked to its end.

use std::collections::BTreeMap;

use cpu::{CS, Cpu, SP, SS, Step};

use crate::{LOAD_SEG, Machine, hw::IoEvent};

/// The routine stopped early; continue interpreting from the current CS:IP.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Bail;

/// A recompiled routine, started at `pc`: its entry, or (resuming after a
/// bail) any of its block leaders. Started at the entry, the return address
/// is on the stack.
pub type Routine = fn(&mut Machine, u16) -> Result<(), Bail>;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RecMode {
    On,
    Shadow,
}

/// Per-routine results of shadow checking.
#[derive(Debug, Default, Clone)]
pub struct ShadowStats {
    /// Calls compared and equal.
    pub ok: u32,
    /// Calls compared and different (first difference in `first_diff`).
    pub diff: u32,
    /// Equal, but Rust bailed somewhere (e.g. for an interrupt inside a
    /// block) and the interpreter ran part of the call.
    pub bailed: u32,
    /// Not compared: the call ran too long.
    pub skipped: u32,
    pub first_diff: Option<String>,
}

pub struct Rec {
    pub mode: RecMode,
    /// Routine by seg000 offset of its entry.
    pub table: Vec<Option<Routine>>,
    /// Routine to resume in, by seg000 offset of any of its block leaders
    /// (entries included): after a bail, Rust takes over again at the next
    /// leader the interpreter reaches.
    pub resume: Vec<Option<Routine>>,
    /// Shadow mode: calls checked per routine.
    pub samples: u32,
    pub stats: BTreeMap<u16, ShadowStats>,
    /// `On` mode: entries into Rust (calls and resumptions), and bails.
    pub calls: u64,
    pub bails: u64,
    /// `On` mode profile: bails by the seg000 offset they left at, and
    /// instructions generated code ran through the interpreter, by opcode.
    pub bail_at: Vec<u64>,
    /// Per routine entry: calls of its Rust code that returned without
    /// bailing (so all of it ran in Rust).
    pub returned: Vec<u32>,
    pub stepped_op: Vec<u64>,
    /// Shadow replays: instructions run by Rust and by the interpreter.
    pub replay_native: u64,
    pub replay_interp: u64,
    /// While a routine runs from shadow checking: nested code it cannot run
    /// natively is interpreted to completion instead of bailing.
    pub(crate) interp_nested: bool,
    /// Bails absorbed by [`Machine::finish_call`] during the current
    /// shadow replay (the call then counts as bailed: part of it was
    /// interpreted).
    nested_bails: u32,
    /// Shadow replays: a readable port's stretch run through an interrupt
    /// due inside it, waiting for the next boundary (see
    /// [`Machine::rec_stretch`]).
    defer: Option<Deferred>,
    /// Shadow replays: stretches run through an interrupt, and how many of
    /// them had to end in a bail (the interrupt changed what the rest of
    /// the stretch computed).
    pub deferred: u64,
    pub deferred_bailed: u64,
    /// Shadow replays whose result differed only with stretches run through
    /// interrupts, and were equal when replayed bailing at them instead.
    pub deferred_retried: u64,
    /// Bail at interrupts again (the second replay of such a call).
    no_through: bool,
    busy: bool,
    /// Shadow mode: calls in progress, innermost last.
    pending: Vec<Pending>,
    /// After a bail: interpret the instruction there once.
    skip: Option<u16>,
}

/// A shadow check waiting for the original to return.
struct Pending {
    entry: u16,
    f: Routine,
    cpu: Cpu,
    mem: Vec<u8>,
    /// The stack pointer at entry (above the return address once left).
    ss: u16,
    sp: u16,
    /// First event of this call in [`crate::hw::IoLog::events`].
    log_start: usize,
    /// Instruction count at entry.
    cpu_instructions: u64,
}

/// A stretch started at `cpu` (its first instruction) with a recorded
/// interrupt due inside it, run by Rust without it.
struct Deferred {
    cpu: Cpu,
    mem: Vec<u8>,
    log: Option<(usize, usize)>,
}

/// seg000's code, physical, and the byte the program patches itself
/// (the immediate of `mov ax, 25h` at C13B).
const CODE_START: usize = (LOAD_SEG as usize) << 4;
const CODE_END: usize = CODE_START + 0xf4b0;
const PATCHED: usize = CODE_START + 0xc13c;

/// Pending checks kept at most (each holds a copy of memory).
const MAX_PENDING: usize = 32;

/// Instructions the interpreter may spend finishing one routine; also the
/// longest call that is checked.
const BUDGET: u64 = 50_000_000;

/// `--rec on`: instructions an `INT` or far call may take on the
/// interpreter before the routine leaves it to the run loop.
const ON_INTERP_BUDGET: u32 = 20_000;

/// Recorded events kept at most; past this, pending checks are dropped.
const MAX_EVENTS: usize = 1 << 21;

impl Rec {
    pub fn new(mode: RecMode, routines: &[(u16, Routine)], leaders: &[(u16, Routine)]) -> Rec {
        let mut table = vec![None; 0x10000];
        let mut resume = vec![None; 0x10000];
        for &(off, f) in leaders {
            resume[off as usize] = Some(f);
        }
        for &(off, f) in routines {
            table[off as usize] = Some(f);
            resume[off as usize] = Some(f);
        }
        Rec {
            mode,
            table,
            resume,
            samples: 20,
            stats: BTreeMap::new(),
            calls: 0,
            bails: 0,
            bail_at: vec![0; 0x10000],
            returned: vec![0; 0x10000],
            stepped_op: vec![0; 256],
            replay_native: 0,
            replay_interp: 0,
            interp_nested: false,
            nested_bails: 0,
            defer: None,
            deferred: 0,
            deferred_bailed: 0,
            deferred_retried: 0,
            no_through: false,
            busy: false,
            skip: None,
            pending: Vec::new(),
        }
    }
}

impl Machine {
    /// Run-loop hook: called before each instruction when `rec` is set.
    /// Returns true if it changed the state (the loop must re-check).
    pub(crate) fn rec_hook(&mut self) -> bool {
        let (cs, ip) = (self.cpu.sregs[CS], self.cpu.ip);
        if cs != LOAD_SEG {
            return false;
        }
        let Some(rec) = &mut self.rec else { return false };
        if rec.busy || rec.skip.take() == Some(ip) {
            return false;
        }
        match rec.mode {
            RecMode::On => {
                // A breakpoint (harnesses) must stop at its exact instruction,
                // which Rust code would run through: interpret meanwhile.
                if self.break_at.is_some() {
                    return false;
                }
                let Some(f) = rec.resume[ip as usize] else { return false };
                rec.calls += 1;
                rec.busy = true;
                let r = f(self, ip);
                let rec = self.rec.as_mut().unwrap();
                rec.busy = false;
                if r.is_err() {
                    rec.bails += 1;
                    rec.skip = Some(self.cpu.ip);
                    if self.cpu.sregs[CS] == LOAD_SEG {
                        rec.bail_at[self.cpu.ip as usize] += 1;
                    }
                }
                true
            }
            RecMode::Shadow => {
                let Some(f) = rec.table[ip as usize] else { return false };
                let st = rec.stats.entry(ip).or_default();
                let checked = st.ok + st.diff + st.bailed + st.skipped;
                let in_flight = rec.pending.iter().filter(|p| p.entry == ip).count() as u32;
                let room = checked + in_flight < rec.samples && rec.pending.len() < MAX_PENDING;
                let (ss, sp) = (self.cpu.sregs[SS], self.cpu.regs[SP]);
                let ret = self.mem_read16(ss, sp);
                // Only real calls: an entry reached by a jump or by falling
                // through has no return address on the stack.
                if room && self.called_from(ret, ip) {
                    self.push_check(ip, f);
                }
                false
            }
        }
    }

    fn push_check(&mut self, entry: u16, f: Routine) {
        let p = Pending {
            entry,
            f,
            cpu: self.cpu.clone(),
            mem: self.hw.mem.clone(),
            ss: self.cpu.sregs[SS],
            sp: self.cpu.regs[SP],
            log_start: self.hw.io_log.events.len(),
            cpu_instructions: self.cpu.instructions,
        };
        self.rec.as_mut().unwrap().pending.push(p);
        self.hw.io_log.recording = true;
    }

    /// Shadow mode, for harnesses that call a routine themselves: check the
    /// call starting now (CS:IP at a routine's entry, the return address
    /// pushed), whatever the sample count. False if there is no routine here.
    pub fn rec_check_here(&mut self) -> bool {
        let ip = self.cpu.ip;
        let f = match &self.rec {
            Some(r) if r.mode == RecMode::Shadow && self.cpu.sregs[CS] == LOAD_SEG => r.table[ip as usize],
            _ => None,
        };
        let Some(f) = f else { return false };
        self.push_check(ip, f);
        true
    }

    /// Drop the checks in progress (before loading another state). Returns
    /// how many there were.
    pub fn rec_drop_checks(&mut self) -> usize {
        let Some(rec) = &mut self.rec else { return 0 };
        let n = rec.pending.len();
        rec.pending.clear();
        self.hw.io_log.recording = false;
        self.hw.io_log.events.clear();
        n
    }

    /// Whether the seg000 code just before `ret` is a near call that can
    /// have gone to `target` (direct `CALL rel16` to it, or an indirect
    /// `CALL r/m16` of 2 to 4 bytes).
    fn called_from(&self, ret: u16, target: u16) -> bool {
        let at = |off: u16| self.hw.mem[((LOAD_SEG as usize) << 4) + off as usize];
        if at(ret.wrapping_sub(3)) == 0xe8 {
            let rel = u16::from_le_bytes([at(ret.wrapping_sub(2)), at(ret.wrapping_sub(1))]);
            if ret.wrapping_add(rel) == target {
                return true;
            }
        }
        (2..=4).any(|n| {
            let modrm = at(ret.wrapping_sub(n - 1));
            at(ret.wrapping_sub(n)) == 0xff && (modrm >> 3) & 7 == 2 && modrm_len(modrm) == n - 1
        })
    }

    /// Shadow mode, before each instruction: has the innermost pending call
    /// returned (or been abandoned)?
    pub(crate) fn rec_pending(&mut self) {
        let Some(rec) = &mut self.rec else { return };
        if rec.pending.is_empty() {
            return;
        }
        // Calls too long to check, or too many recorded events: drop the
        // oldest pending check.
        let first = &rec.pending[0];
        if self.cpu.instructions - first.cpu.instructions > BUDGET || self.hw.io_log.events.len() > MAX_EVENTS {
            let p = rec.pending.remove(0);
            rec.stats.entry(p.entry).or_default().skipped += 1;
            let keep = rec.pending.first().map_or(self.hw.io_log.events.len(), |p| p.log_start);
            self.hw.io_log.events.drain(..keep);
            for p in &mut rec.pending {
                p.log_start -= keep;
            }
        }
        // The stack is above a call's entry frame: it returned to its caller,
        // or left it some other way (a routine that pops its own return
        // address, or ends in a jump chain dropping the frame). The replay
        // runs exactly as many instructions and must end in this same state.
        // Several calls can be left at once: all are checked at this point.
        loop {
            let rec = self.rec.as_mut().unwrap();
            let Some(p) = rec.pending.last() else { break };
            let c = &self.cpu;
            if c.sregs[SS] != p.ss || c.regs[SP] <= p.sp {
                break;
            }
            let p = rec.pending.pop().unwrap();
            self.shadow_replay(p);
        }
        let rec = self.rec.as_mut().unwrap();
        if rec.pending.is_empty() {
            self.hw.io_log.recording = false;
            self.hw.io_log.events.clear();
        }
    }

    /// Replay a routine's Rust version from its entry state, fed with what
    /// the original received (port reads, interrupts, BIOS/DOS results), and
    /// compare it with the original's result (the current state), which is
    /// then restored.
    fn shadow_replay(&mut self, p: Pending) {
        // A call that wrote into the code segment (other than the known
        // patch site) is marked in the report: if it changed code, the Rust
        // version, which keeps the code as it was, runs differently.
        let code = CODE_START..CODE_END;
        let code_changed = p.mem[code.clone()].iter().zip(&self.hw.mem[code.clone()]).enumerate().any(|(i, (a, b))| a != b && CODE_START + i != PATCHED);
        let entry_state = (p.cpu.clone(), p.mem.clone());
        let cpu1 = std::mem::replace(&mut self.cpu, p.cpu);
        let mem1 = std::mem::replace(&mut self.hw.mem, p.mem);
        let io1 = self.hw.io_count;
        let ints1 = self.int_counts;
        let end = self.hw.io_log.events.len();
        self.hw.io_log.recording = false;
        self.hw.io_log.replay = Some((p.log_start, end));
        self.hw.io_log.mismatch = None;
        self.hw.io_log.stop_at = cpu1.instructions;
        let rec = self.rec.as_mut().unwrap();
        rec.interp_nested = true;
        rec.busy = true;
        let mut retried = false;
        let (diff, bails) = loop {
            let deferred0 = self.rec.as_ref().unwrap().deferred;
            let (finished, bails) = self.replay_drive(p.entry, p.f);
            let unused = self.hw.io_log.peek().map(|e| crate::hw::describe(Some(e)));
            let mismatch = self.hw.io_log.mismatch.take().or_else(|| unused.map(|e| format!("io: original also had {e}")));
            let diff = match (mismatch, finished) {
                (Some(m), _) => Some(m),
                (None, false) => Some(format!(
                    "did not finish: at {:04x}:{:04x} after {} instructions, original {}",
                    self.cpu.sregs[CS],
                    self.cpu.ip,
                    self.cpu.instructions - p.cpu_instructions,
                    cpu1.instructions - p.cpu_instructions
                )),
                (None, true) => compare(&cpu1, &mem1, &self.cpu, &self.hw.mem),
            };
            // A port may keep what it read across a stretch (right under
            // `--rec on`, where no interrupt comes while Rust runs); run
            // through an interrupt, that can be stale. Such a result is
            // checked again bailing at the interrupts, unless a stretch
            // itself was found different.
            let rec = self.rec.as_mut().unwrap();
            let through = rec.deferred > deferred0;
            let stretch_wrong = diff.as_deref().is_some_and(|d| d.starts_with("stretch from"));
            if diff.is_none() || !through || stretch_wrong || retried {
                rec.no_through = false;
                break (diff, bails + retried as u32);
            }
            retried = true;
            rec.no_through = true;
            rec.deferred_retried += 1;
            rec.defer = None;
            self.cpu = entry_state.0.clone();
            self.hw.mem.copy_from_slice(&entry_state.1);
            self.hw.io_log.replay = Some((p.log_start, end));
            self.hw.io_log.mismatch = None;
        };
        self.hw.io_log.replay = None;
        self.hw.io_log.recording = true;
        let rec = self.rec.as_mut().unwrap();
        rec.interp_nested = false;
        rec.busy = false;
        let diff = diff.map(|d| if code_changed { format!("{d} (the call wrote into the code segment)") } else { d });
        let st = rec.stats.entry(p.entry).or_default();
        match &diff {
            Some(d) => {
                st.diff += 1;
                if st.first_diff.is_none() {
                    st.first_diff = Some(d.clone());
                }
            }
            None if bails > 0 => st.bailed += 1,
            None => st.ok += 1,
        }
        // Carry on from the original's result.
        self.cpu = cpu1;
        self.hw.mem = mem1;
        self.hw.io_count = io1;
        self.int_counts = ints1;
    }

    /// Shadow replay: run routine `f` from its entry for as many
    /// instructions as the original's call took (`IoLog::stop_at`), resuming
    /// in Rust at every block leader and interpreting only where Rust bailed.
    /// Returns (finished, bails).
    fn replay_drive(&mut self, entry: u16, f: Routine) -> (bool, u32) {
        let stop = self.hw.io_log.stop_at;
        let start = self.cpu.instructions;
        let interp0 = self.rec.as_ref().unwrap().replay_interp;
        self.rec.as_mut().unwrap().nested_bails = 0;
        self.hw.io_log.stopped = false;
        let r = f(self, entry);
        let mut just_bailed = self.rec_settle().and(r).is_err();
        if !just_bailed {
            self.rec.as_mut().unwrap().returned[entry as usize] += 1;
        }
        let mut bails = (just_bailed && !self.hw.io_log.stopped) as u32;
        let finished = loop {
            if self.cpu.instructions >= stop {
                break self.cpu.instructions == stop;
            }
            if self.replay_irq() {
                just_bailed = false;
                continue;
            }
            if self.hw.io_log.mismatch.is_some() || self.cpu.instructions - start > BUDGET {
                break false;
            }
            let ip = self.cpu.ip;
            let resume = if self.cpu.sregs[CS] == LOAD_SEG && !just_bailed {
                self.rec.as_ref().and_then(|r| r.resume[ip as usize])
            } else {
                None
            };
            if let Some(g) = resume {
                self.hw.io_log.stopped = false;
                let r = g(self, ip);
                just_bailed = self.rec_settle().and(r).is_err();
                bails += (just_bailed && !self.hw.io_log.stopped) as u32;
            } else {
                just_bailed = false;
                if self.step_insn().is_err() {
                    break false;
                }
            }
        };
        let rec = self.rec.as_mut().unwrap();
        let interp = rec.replay_interp - interp0;
        rec.replay_native += (self.cpu.instructions - start).saturating_sub(interp);
        (finished, bails + rec.nested_bails)
    }

    /// Replay: deliver the next recorded interrupt if it is due now (or the
    /// CPU is halted waiting for it). True if one was delivered.
    fn replay_irq(&mut self) -> bool {
        match self.hw.io_log.peek() {
            Some(&IoEvent::Irq { vector, at }) if at == self.cpu.instructions || self.cpu.halted => {
                self.hw.io_log.advance();
                self.cpu.interrupt(&mut self.hw, vector);
                true
            }
            Some(&IoEvent::Irq { at, .. }) if at < self.cpu.instructions => {
                let now = self.cpu.instructions;
                self.hw.io_log.fail(format!("irq missed: due before instruction {at}, now {now}"));
                false
            }
            _ => false,
        }
    }

    /// Replay: a BIOS/DOS service the replay reached; apply the original's.
    pub(crate) fn replay_service(&mut self, n: u8) {
        let log = &mut self.hw.io_log;
        let ev = match log.peek() {
            Some(e @ IoEvent::Callback { n: k, .. }) if *k == n => {
                let e = e.clone();
                log.advance();
                e
            }
            other => {
                let what = crate::hw::describe(other);
                log.fail(format!("io: service int {n:02x}, original: {what}"));
                return;
            }
        };
        let IoEvent::Callback { before, after, writes, .. } = ev else { unreachable!() };
        if let Some(d) = compare_cpu(&before, &self.cpu) {
            self.hw.io_log.fail(format!("io: service int {n:02x} asked with different registers: {d}"));
            return;
        }
        let count = self.cpu.instructions;
        self.cpu = *after;
        self.cpu.instructions = count;
        for (a, v) in writes {
            self.hw.mem[a as usize] = v;
        }
    }

    /// For generated code, at the start of a block of `len` instructions:
    /// true when the routine must stop there (it bails).
    /// - Running (`--rec on`): an interrupt is pending, or a device event or
    ///   the run's deadline falls inside the block: the interpreter runs it,
    ///   so all of these happen at the same instruction as without `--rec`
    ///   (and a native loop polling a timer variable sees it change).
    /// - Shadow replay: a recorded interrupt, or the end of the original's
    ///   call, falls in this block; the interpreter gets there exactly.
    #[inline]
    pub fn rec_tick(&mut self, len: u32) -> bool {
        if self.hw.io_log.replay.is_some() {
            let end = self.cpu.instructions + len as u64;
            if matches!(self.hw.io_log.peek(), Some(&IoEvent::Irq { at, .. }) if at < end) {
                return true;
            }
            self.hw.io_log.stopped = self.hw.io_log.stop_at < end;
            return self.hw.io_log.stopped;
        }
        if self.rec.as_ref().is_some_and(|r| r.interp_nested) {
            return false;
        }
        // The run loop checks before every instruction; the block's last
        // instruction starts at this count. Time comes from the count, so a
        // device event or the run's deadline inside the block is known now.
        let last = self.now_at(self.cpu.instructions + len.max(1) as u64 - 1);
        last >= self.next_event || last >= self.run_deadline || self.hw.reschedule || (self.cpu.accepts_irq() && self.hw.irq_pending())
    }

    fn interp_until(&mut self, budget: u64, done: impl Fn(&Cpu) -> bool) -> Result<(), Bail> {
        for _ in 0..budget {
            if done(&self.cpu) {
                return Ok(());
            }
            if self.hw.io_log.replay.is_some() && self.cpu.instructions >= self.hw.io_log.stop_at {
                return Err(Bail);
            }
            self.step_insn()?;
        }
        Err(Bail)
    }

    /// Execute the instruction at CS:IP with the interpreter (BIOS/DOS
    /// services run, no interrupts). For generated code. During a shadow
    /// replay, a recorded interrupt due now is delivered instead.
    pub fn step_insn(&mut self) -> Result<(), Bail> {
        let replay = self.hw.io_log.replay.is_some();
        if replay && self.replay_irq() {
            return Ok(());
        }
        if replay {
            let n = self.cpu.instructions;
            let r = self.step_raw();
            let rec = self.rec.as_mut().unwrap();
            rec.replay_interp += self.cpu.instructions - n;
            return r;
        }
        if let Some(rec) = &mut self.rec
            && rec.mode == RecMode::On
        {
            // Skip prefixes: the opcode that needed the interpreter.
            let base = (self.cpu.sregs[CS] as usize) << 4;
            let mut off = self.cpu.ip;
            let mut op = self.hw.mem[(base + off as usize) & 0xf_ffff];
            while matches!(op, 0x26 | 0x2e | 0x36 | 0x3e | 0xf0 | 0xf2 | 0xf3) {
                off = off.wrapping_add(1);
                op = self.hw.mem[(base + off as usize) & 0xf_ffff];
            }
            rec.stepped_op[op as usize] += 1;
        }
        self.step_raw()
    }

    fn step_raw(&mut self) -> Result<(), Bail> {
        let replay = self.hw.io_log.replay.is_some();
        self.hw.now_ns = self.now_ns();
        match self.cpu.step(&mut self.hw) {
            Step::Ok => Ok(()),
            Step::Callback(n) => {
                self.service(n);
                Ok(())
            }
            Step::Halt if replay && matches!(self.hw.io_log.peek(), Some(IoEvent::Irq { .. })) => Ok(()),
            Step::Halt | Step::Invalid { .. } => Err(Bail),
        }
    }

    /// For generated code: the instruction at `ip` (seg000) is one the
    /// routine does not run natively (`INT`, far call, unknown target).
    /// Under shadow checking it is interpreted until execution is back at
    /// `next` with the same stack pointer; otherwise the routine bails with
    /// CS:IP on that instruction.
    pub fn rec_interp(&mut self, ip: u16, next: u16) -> Result<(), Bail> {
        self.cpu.ip = ip;
        self.rec_settle()?;
        let nested = self.rec.as_ref().is_some_and(|r| r.interp_nested);
        let (cs, ss, sp) = (self.cpu.sregs[CS], self.cpu.sregs[SS], self.cpu.regs[SP]);
        let back = |c: &Cpu| c.sregs[CS] == cs && c.ip == next && c.sregs[SS] == ss && c.regs[SP] == sp;
        if nested {
            self.step_insn()?;
            return self.interp_until(BUDGET, back);
        }
        // The graphics model check watches every instruction: leave these to
        // the run loop then. (Music driver calls are tracked here as there.)
        if self.gfx.active() {
            return Err(Bail);
        }
        // Running: BIOS/DOS services and driver calls are short; interpret
        // them here. One that takes long (it waits for an interrupt) is left
        // to the run loop, mid-way. After a service that showed the program
        // idle, the run loop must sleep: bail there too.
        for _ in 0..ON_INTERP_BUDGET {
            if self.music.watch[0] != 0 {
                let pc = self.cpu.phys(self.cpu.sregs[CS], self.cpu.ip);
                if let Some(entry) = self.music.hit(pc) {
                    self.on_music_call(entry);
                }
            }
            self.hw.now_ns = self.now_ns();
            match self.cpu.step(&mut self.hw) {
                Step::Ok => {}
                Step::Callback(n) => {
                    self.service(n);
                    if self.idle_check() {
                        return Err(Bail);
                    }
                }
                Step::Halt | Step::Invalid { .. } => return Err(Bail),
            }
            if back(&self.cpu) {
                return Ok(());
            }
            // An interrupt or device event due: the run loop takes it now,
            // as it would have between these instructions.
            if self.exited.is_some() || self.rec_tick(1) {
                return Err(Bail);
            }
        }
        Err(Bail)
    }

    /// For generated code: call the routine at seg000 `target` with the
    /// return address `ret` already pushed. Uses its Rust version when there
    /// is one, else interprets it (shadow checking) or bails. On `Ok`, the
    /// callee has returned to `ret`.
    pub fn rec_call(&mut self, target: u16, ret: u16) -> Result<(), Bail> {
        self.cpu.ip = target;
        let nested = self.rec.as_ref().is_some_and(|r| r.interp_nested);
        let (ss, sp) = (self.cpu.sregs[SS], self.cpu.regs[SP]);
        self.rec_settle()?;
        if let Some(f) = self.rec.as_ref().and_then(|r| r.table[target as usize]) {
            let r = f(self, target);
            let r = self.rec_settle().and(r);
            match r {
                Ok(()) => {
                    if let Some(r) = self.rec.as_mut() {
                        r.returned[target as usize] += 1;
                    }
                }
                // Shadow replay: the callee bailed (an interrupt due inside
                // it, a wait for one, code it does not run): finish it here
                // and carry on in the caller's Rust code.
                Err(Bail) if nested => self.finish_call(ret, ss, sp)?,
                Err(e) => return Err(e),
            }
        } else if nested {
            self.finish_call(ret, ss, sp)?;
        } else {
            return Err(Bail);
        }
        if self.cpu.ip == ret && self.cpu.sregs[CS] == LOAD_SEG { Ok(()) } else { Err(Bail) }
    }

    /// For readable ports, at the start of a stretch of `len` instructions
    /// from CS:IP (already set): true when the port must bail there, as
    /// [`Machine::rec_tick`]. First settles a stretch run through an
    /// interrupt before ([`Machine::rec_settle`]); on `Err` the port bails
    /// with the state the interpreter left.
    ///
    /// With `through` (a stretch without port I/O), in a shadow replay, a
    /// recorded interrupt due inside the stretch does not make it bail: the
    /// port runs the stretch without it, and at the next boundary the
    /// stretch is checked and the interrupt put in (see `rec_settle`). A
    /// port whose own loops always meet an interrupt is then still run to
    /// its end in Rust.
    pub fn rec_stretch(&mut self, len: u32, through: bool) -> Result<bool, Bail> {
        self.rec_settle()?;
        if self.hw.io_log.replay.is_none() || !through || self.rec.as_ref().is_some_and(|r| r.no_through) {
            return Ok(self.rec_tick(len));
        }
        let end = self.cpu.instructions + len as u64;
        self.hw.io_log.stopped = self.hw.io_log.stop_at < end;
        if self.hw.io_log.stopped {
            return Ok(true);
        }
        let due = matches!(self.hw.io_log.peek(), Some(&IoEvent::Irq { at, .. }) if at < end);
        if due && self.hw.io_log.mismatch.is_none() {
            let d = Deferred { cpu: self.cpu.clone(), mem: self.hw.mem.clone(), log: self.hw.io_log.replay };
            let rec = self.rec.as_mut().unwrap();
            rec.defer = Some(d);
            rec.deferred += 1;
        }
        Ok(false)
    }

    /// Shadow replay, at a port's boundary after a stretch it ran through an
    /// interrupt (CS:IP set to where the original is then): the stretch is
    /// interpreted from its start twice. Without the interrupts, it must
    /// give exactly the port's state (else the replay fails: the port
    /// differs). With them, delivered at their instruction, it gives the
    /// original's state, which the port goes on from. If the interrupts
    /// changed registers, flags or where the stretch ended (the port's
    /// locals may hold what the rest of it computed), the port bails there
    /// instead (the call counts as bailed).
    pub fn rec_settle(&mut self) -> Result<(), Bail> {
        let Some(rec) = self.rec.as_mut() else { return Ok(()) };
        let Some(d) = rec.defer.take() else { return Ok(()) };
        let now = self.cpu.instructions;
        let start = d.cpu.instructions;
        let at = d.cpu.ip;
        // Without the interrupts.
        let r_cpu = std::mem::replace(&mut self.cpu, d.cpu.clone());
        let r_mem = std::mem::replace(&mut self.hw.mem, d.mem.clone());
        let r_log = std::mem::replace(&mut self.hw.io_log.replay, d.log);
        let mut ok = now >= start;
        while ok && self.cpu.instructions < now {
            let n = self.cpu.instructions;
            ok = self.step_raw().is_ok() && self.hw.io_log.mismatch.is_none() && self.cpu.instructions > n;
        }
        let pure = if ok { compare(&self.cpu, &self.hw.mem, &r_cpu, &r_mem) } else { None };
        let pure_log = self.hw.io_log.replay;
        let p_cpu = self.cpu.clone();
        self.hw.io_log.mismatch = None;
        if !ok {
            // Not interpretable on its own (port I/O after the interrupt):
            // the port's state can't be checked.
            self.hw.io_log.fail(format!("stretch from {at:04x} through an interrupt: not replayable without it"));
        } else if let Some(diff) = pure {
            self.hw.io_log.fail(format!("stretch from {at:04x} differs: {diff}"));
        } else if pure_log != r_log {
            self.hw.io_log.fail(format!("stretch from {at:04x} did different I/O"));
        }
        if self.hw.io_log.mismatch.is_some() {
            self.cpu = r_cpu;
            self.hw.mem = r_mem;
            self.hw.io_log.replay = r_log;
            return Err(Bail);
        }
        // With them: the original.
        self.cpu = d.cpu;
        self.hw.mem = d.mem;
        self.hw.io_log.replay = d.log;
        let pure_n = now - start;
        let mut own = 0u64;
        let mut frames: Vec<(u16, u16, u16, u16)> = Vec::new();
        while own < pure_n || !frames.is_empty() {
            if self.hw.io_log.mismatch.is_some() || self.cpu.instructions - start > BUDGET {
                return Err(Bail);
            }
            // The original's call ended inside the stretch (it left its
            // frame some other way than its `ret`): the replay ends here.
            if self.cpu.instructions >= self.hw.io_log.stop_at {
                self.hw.io_log.stopped = true;
                return Err(Bail);
            }
            let c = &self.cpu;
            let frame = (c.sregs[CS], c.ip, c.sregs[SS], c.regs[SP]);
            if self.replay_irq() {
                frames.push(frame);
                continue;
            }
            let inside = !frames.is_empty();
            let n = self.cpu.instructions;
            self.step_raw()?;
            // The handlers' instructions are interpreted; the stretch's own
            // ones were run by the port.
            if inside {
                self.rec.as_mut().unwrap().replay_interp += self.cpu.instructions - n;
            } else {
                own += self.cpu.instructions - n;
            }
            let c = &self.cpu;
            let here = (c.sregs[CS], c.ip, c.sregs[SS], c.regs[SP]);
            while frames.last() == Some(&here) {
                frames.pop();
            }
        }
        let c = &self.cpu;
        let same = c.ip == p_cpu.ip && c.regs == p_cpu.regs && c.sregs == p_cpu.sregs && c.flags() == p_cpu.flags();
        if same {
            Ok(())
        } else {
            let rec = self.rec.as_mut().unwrap();
            rec.deferred_bailed += 1;
            rec.nested_bails += 1;
            Err(Bail)
        }
    }

    /// Shadow replay: run until the call whose return address `ret` was
    /// pushed at SS:SP returns there, the way [`Machine::replay_drive`]
    /// runs a check: recorded interrupts delivered at their instruction,
    /// Rust resumed at every block leader, the interpreter elsewhere. Bails
    /// at the end of the original's call (or on an I/O mismatch), which the
    /// replay then ends with.
    fn finish_call(&mut self, ret: u16, ss: u16, sp: u16) -> Result<(), Bail> {
        let start = self.cpu.instructions;
        let mut just_bailed = true;
        self.rec.as_mut().unwrap().nested_bails += 1;
        loop {
            let c = &self.cpu;
            if c.sregs[CS] == LOAD_SEG && c.ip == ret && c.sregs[SS] == ss && c.regs[SP] > sp {
                return Ok(());
            }
            if self.hw.io_log.replay.is_some() && self.cpu.instructions >= self.hw.io_log.stop_at {
                return Err(Bail);
            }
            if self.hw.io_log.mismatch.is_some() || self.cpu.instructions - start > BUDGET {
                return Err(Bail);
            }
            if self.replay_irq() {
                just_bailed = false;
                continue;
            }
            let ip = self.cpu.ip;
            let resume = if self.cpu.sregs[CS] == LOAD_SEG && !just_bailed {
                self.rec.as_ref().and_then(|r| r.resume[ip as usize])
            } else {
                None
            };
            if let Some(g) = resume {
                self.hw.io_log.stopped = false;
                let r = g(self, ip);
                just_bailed = self.rec_settle().and(r).is_err();
                if just_bailed {
                    self.rec.as_mut().unwrap().nested_bails += 1;
                }
            } else {
                just_bailed = false;
                self.step_insn()?;
            }
        }
    }
}

/// Bytes of a ModRM operand (ModRM, displacement), 16-bit addressing.
fn modrm_len(modrm: u8) -> u16 {
    match (modrm >> 6, modrm & 7) {
        (0, 6) => 3,
        (0, _) | (3, _) => 1,
        (1, _) => 2,
        _ => 3,
    }
}

/// First register difference between two CPU states, if any.
fn compare_cpu(c1: &Cpu, c2: &Cpu) -> Option<String> {
    for (i, (a, b)) in c1.regs.iter().zip(&c2.regs).enumerate() {
        if a != b {
            return Some(format!("reg {} {a:04x} vs {b:04x}", ["AX", "CX", "DX", "BX", "SP", "BP", "SI", "DI"][i]));
        }
    }
    for (i, (a, b)) in c1.sregs.iter().zip(&c2.sregs).enumerate() {
        if a != b {
            return Some(format!("sreg {} {a:04x} vs {b:04x}", ["ES", "CS", "SS", "DS"][i]));
        }
    }
    if c1.ip != c2.ip {
        return Some(format!("ip {:04x} vs {:04x}", c1.ip, c2.ip));
    }
    // Flags the 286 leaves undefined after some instructions are compared
    // too: the interpreter's values are the reference.
    if c1.flags() != c2.flags() {
        return Some(format!("flags {:04x} vs {:04x}", c1.flags(), c2.flags()));
    }
    None
}

/// First difference between two machine states, if any.
fn compare(c1: &Cpu, m1: &[u8], c2: &Cpu, m2: &[u8]) -> Option<String> {
    if let Some(d) = compare_cpu(c1, c2) {
        return Some(d);
    }
    if m1 != m2 {
        let i = m1.iter().zip(m2).position(|(a, b)| a != b).unwrap();
        return Some(format!("mem {:05x}: {:02x} vs {:02x}", i, m1[i], m2[i]));
    }
    None
}

